"""Rebuild the dated Blondshell audit from its captured Campaign Coach API rows.
Run: python scripts/build-blondshell.py. Source endpoints and cohort rules are in
public/blondshell/research-2026-11-17.json and BLONDSHELL-internal-audit.md.
Does not change source data, other presentations, or retrieve mutable counters.
"""
from pathlib import Path
import json, datetime as dt, collections, statistics, html, math
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'public/blondshell'
D=json.loads((OUT/'research-2026-11-17.json').read_text()); V=D['videos']; by={v['id']:v for v in V}
day=lambda x:dt.date.fromisoformat(x[:10]); R=day('2026-09-25'); P=day('2025-05-02'); END=day('2026-11-17')
esc=lambda x:html.escape(str(x),quote=True)
def fmt(n):return f'{n/1e6:.2f}m' if n>=1e6 else f'{n/1e3:.1f}k' if n>=1000 else str(n)
def date(s):return day(s).strftime('%d %b %Y').lstrip('0')
def typ(v):
 t=v['title'].lower()
 if not v['durationSec']:return 'Unavailable / zero-duration'
 if v['isShort']:return 'Short¹'
 if 'live' in t or 'dscvr' in t:return 'Live / session'
 if 'lyric' in t:return 'Lyric video'
 if 'visualiz' in t or 'visualis' in t:return 'Visualizer'
 if 'music video' in t:return 'Music video'
 if 'audio' in t:return 'Official audio'
 return 'Other'
def cohort(a,b):return sorted([v for v in V if a<=day(v['publishedAt'])<=b and v['durationSec']>0],key=lambda v:v['publishedAt'])
C=cohort(day('2026-05-14'),END); M=cohort(R-dt.timedelta(days=130),END); OLD=cohort(P-dt.timedelta(days=130),P+dt.timedelta(days=53)); FULL=cohort(day('2024-08-12'),P+dt.timedelta(days=53)); L=[v for v in C if not v['isShort']]; S=[v for v in C if v['isShort']]
POST=cohort(R+dt.timedelta(days=1),END); PRE=cohort(day('2026-05-14'),R-dt.timedelta(days=1)); RELEASE=cohort(R,R)
SUM=lambda a:sum(v['views'] for v in a)
def stats(v,a,b):
 days=sorted(set(day(x['publishedAt']) for x in v));return {'uploads':len(v),'shorts':sum(x['isShort'] for x in v),'fullLength':sum(not x['isShort'] for x in v),'activeWeeks':len(set((d-a).days//7 for d in days)),'weekBins':(b-a).days//7+1,'longestGapDays':max((y-x).days for x,y in zip(days,days[1:]))}
assert len(by)==len(V)==520 and D['retrieved']==520 and D['capped'] is False
assert len(C)==110 and len(L)==11 and len(S)==99 and SUM(L)==396051 and SUM(C)==675544
assert len(RELEASE)==15 and len(POST)==24 and all(v['isShort'] for v in POST)
assert D['channel']['id']==D['snapshots']['channelId']==D['shelf']['channelId']
A={'capturedAt':D['fetchedAt'],'release':'2026-09-25','previousRelease':'2025-05-02','currentWindow':{'start':'2026-05-14','end':'2026-11-17','uploads':len(C),'fullSongUploads':len(L),'shorts':len(S),'lifetimeViewsOnWindowUploads':SUM(C),'lifetimeViewsOnAlbumFullSongs':SUM(L),'lifetimeViewsOnShorts':SUM(S),'formats':{k:{'uploads':sum(typ(v)==k for v in C),'lifetimeViews':SUM([v for v in C if typ(v)==k])} for k in sorted(set(map(typ,C))) }},'matchedWindows':{'relativeDays':[-130,53],'current':stats(M,R-dt.timedelta(days=130),END),'previous':stats(OLD,P-dt.timedelta(days=130),P+dt.timedelta(days=53))},'coverage':{'retrievedRows':len(V),'publicVideoCounter':D['channel']['publicVideoCount'],'rowViews':SUM(V),'channelLifetimeViews':D['channel']['lifetimeViews'],'unreconciledViewDifference':D['channel']['lifetimeViews']-SUM(V)},'postRelease':{'days':53,'uploads':len(POST),'shorts':len(POST),'newFullSongVersions':0}}
(OUT/'calculations-2026-11-17.json').write_text(json.dumps(A,indent=2))
def photo(id,title=None,meta=None,value=True,frame=False):
 v=by[id];title=title or v['title'].replace('Blondshell - ','');meta=meta or f'{date(v["publishedAt"])} · {typ(v)}'
 val=f'<div class="value">{fmt(v["views"])} <small>lifetime views ↗</small></div>' if value else ''
 return f'<a class="photo {"frame" if frame else ""}" href="https://www.youtube.com/watch?v={id}" target="_blank" rel="noopener"><figure><img src="/blondshell/images/{id}.jpg" width="480" height="360" alt="{esc(title)}" loading="eager"><figcaption>{val}<div class="title">{esc(title)}</div><div class="meta">{esc(meta)}</div></figcaption></figure></a>'

def note(s,kind='API'):return f'<p class="source"><b>{kind}</b> · {s}</p>'
def heading(k,h,lead=''):return f'<span class="label">{k}</span><h2>{h}</h2>'+ (f'<p class="lead">{lead}</p>' if lead else '')
def table(vs,caption=''):
 return f'<div class="table-wrap"><table><caption>{caption}</caption><thead><tr><th>Published</th><th>Upload ↗</th><th>Format</th><th>Lifetime views</th></tr></thead><tbody>'+''.join(f'<tr><td>{v["publishedAt"][:10]}</td><td><a href="https://www.youtube.com/watch?v={v["id"]}" target="_blank" rel="noopener">{esc(v["title"])}</a></td><td>{typ(v)}</td><td>{v["views"]:,}</td></tr>' for v in vs)+'</tbody></table></div>'
def rhythm(vs,a,b):
 n=(b-a).days//7+1; vals=[]
 for i in range(n):
  rows=[v for v in vs if i*7<=(day(v['publishedAt'])-a).days<(i+1)*7];short=sum(v['isShort'] for v in rows);full=len(rows)-short
  vals.append(f'<div class="week" title="{(a+dt.timedelta(days=i*7)).isoformat()}: {full} full-song, {short} Shorts"><i style="height:{short*7}px"></i><b style="height:{full*7}px"></b></div>')
 return '<div class="rhythm" role="img" aria-label="Weekly upload counts; sand Shorts, olive full-song uploads">'+''.join(vals)+'</div><div class="axis"><span>'+date(a.isoformat())+'</span><span>Sand · Shorts &nbsp; Olive · full songs</span><span>'+date(b.isoformat())+'</span></div>'
slides=[]
def slide(id,title,body,theme=''):
 n=len(slides)+1;slides.append(f'<section class="slide {theme}" id="{id}" data-title="{esc(title)}"><div class="inner">{body}</div><div class="folio"><span>Blondshell × YouTube · Partisan Records</span><span>{n:02d} / {esc(title)}</span></div></section>')
