rows=[('Channel uploads',mp['uploads'],mc['uploads']),('Shorts¹',mp['shorts'],mc['shorts']),('Full-length uploads',mp['fullLength'],mc['fullLength']),('Active 7-day bins',f'{mp["activeWeeks"]} / 27',f'{mc["activeWeeks"]} / 27'),('Longest between-upload gap','14 days','16 days'),('New full-song versions, days 1–53','0','0'),('Album tracks covered by release day','12 / 12','11 / 11')]
